public class DS01_1 {
    public static void main(String[] args) {
        String[] samples = {"PAB", "5C", "PABC", "CXY", "CRSI", "7", "B899", "B9"}; //待排序数据集
        quickSort(samples, 0, samples.length - 1);
        for (int i = 0; i < samples.length; i ++) {
            System.out.print(samples[i] + " ");
        }
    }
    //快速排序方法
    private static void quickSort(String[] samples, int start, int end) {
        if(start >= end) {
            return;
        }
        String pivot = samples[start]; //以区间的第一个元素作为基准
        int left = start;
        int right = end;
        while(left < right) {
            //从右向左找第一个小于基准的元素
            while(left < right && myCompare(samples[right], pivot) >= 0) {
                right --;
            }
            samples[left] = samples[right];
            //从左向右找第一个大于基准的元素
            while(left < right && myCompare(samples[left], pivot) <= 0) {
                left ++;
            }
            samples[right] = samples[left];
        }
        samples[left] = pivot; //基准归位
        quickSort(samples, start, left - 1);
        quickSort(samples, left + 1, end);
    }
    //按照给定顺序比较两个字符串的方法
    private static int myCompare(String a, String b) {
        int length = a.length() < b.length() ? a.length() : b.length();
        //逐个字符比较，遇到不同的字符即可确定顺序
        for(int i = 0; i < length; i ++) {
            if(a.charAt(i) != b.charAt(i)) {
                return a.charAt(i) - b.charAt(i);
            }
        }
        //一个字符串是另一个的前缀时，较短的排在前面
        return a.length() - b.length();
    }
}

