//使用深度优先算法寻找一条哈密顿通路，找到即停止
private static void findAWay() {
    stack = new Stack();
    //随机选择一支队伍作为起点
    stack.push(nodeList.get((int)(Math.random() * teamNumber)));
    stack.getTop().setTrue();
    while(!stack.isFull()) {
        //栈已空，重新寻找一个未访问过的队伍作为起点
        if(stack.isEmpty()) {
            for(int i = 0; i < teamNumber; i ++) {
                if(!nodeList.get(i).getHasGet()) {
                    stack.push(nodeList.get(i));
                    stack.getTop().setTrue();
                    break;
                }
            }
        }
        //所有队伍都已访问过但仍未凑出通路
        if(stack.isEmpty()) {
            System.out.println("\n该组数据无哈密顿通路！");
            System.exit(0);
        }
        //收集栈顶队伍可以到达且未被访问过的队伍
        int[] temp = graph[stack.getTop().getIndex()];
        ArrayList<Node> nextList = new ArrayList<>();
        for(int i = 0; i < teamNumber; i ++) {
            if(temp[i] == 1 && !nodeList.get(i).getHasGet()) {
                nextList.add(nodeList.get(i));
            }
        }
        //无路可走则回退，否则随机选择一支队伍继续深入
        if(nextList.isEmpty()) {
            stack.pop();
            continue;
        }
        stack.push(nextList.get((int)(Math.random() * nextList.size())));
        stack.getTop().setTrue();
    }
}
